##this script allows to compare the output of LLM with the Gold Standard (GS) files
### Expected format of the files: .TSV file: # wordform<TAB>lemma
### Sentences are separated by blank lines.

import os

# ================================================
##creating the path for GS and LLM generated files
# ================================================

language = 'language'
folder = 'folder_name'
corpus = 'corpus_name'
file_type = 'test'

prompt_type = 'prompt_type' #e.g. 'basic_prompt_4_shot_random_examples'
model = 'model_name' #e.g. LLAMA, QWEN, MISTRAL

parent_directory = './' + folder + '/'
extension = '.tsv'
path_file_gs = os.path.join(parent_directory + language + '_' + corpus + file_type + extension)
path_file_generated_lemmas = 'path_to_llm_output'

# ================================================
##reading files
# ================================================

def file_read(file:str):
    with open(file, 'r', encoding='utf-8') as f:
        read_file = f.readlines()
    return read_file

gold_standard = file_read(path_file_gs)
generated_lemmas = file_read(path_file_generated_lemmas)

# =================================================
# compare sentence-level lemma lists: GS file
# =================================================

##we obtain two list of lists of strings: 1) the list with wordforms from GS file. 2) the list with lemmas from GS file, sentence by sentence
# it will allow us to make a comparison on a sentence level 
total_tokens_gs = 0
sentence_word_gs = [] ##list of lists with the wordforms for each sentence, where each sentence is saved into a separate list.
sentence_lemma_gs = [] ##same as sentence_word_gs but for lemmas
aux_word_gs = []
aux_lemma_gs = []
for line in gold_standard:
    if line != '\n': #lines that separate each sentence
        total_tokens_gs +=1 ##should display to us the number of tokens in the set
        line = line.strip().split('\t') #deleting the newlines + separating the line by elements
        wordform = line[0]
        lemma = line[1]
        aux_word_gs.append(wordform)
        aux_lemma_gs.append(lemma)
    else:
        sentence_word_gs.append(aux_word_gs)
        sentence_lemma_gs.append(aux_lemma_gs)
        aux_word_gs = []
        aux_lemma_gs = []

print(f'Number of tokens in the GS file:{total_tokens_gs}')

# ======================================================
# compare sentence-level lemma lists: LLM generated file
# ======================================================
#same as with GS file but for the file generated by LLM

total_wordforms_gen = 0
sentence_word_gen = []
sentence_lemma_gen = []
aux_word_gen = []
aux_lemma_gen = []
wrong_element = [] ##to store the output that does not meet the output requirements, such as wrongly separated words or additional symbols the model creates
number_of_wrong_elements = 0
for line in generated_lemmas:
    if line != '\n':
        total_wordforms_gen+=1
        line = line.strip().split('\t')
        if len(line) == 2: ##we have 2 elements in line after performing the split, which should be wordform and lemma
            wordformGEN = line[0]
            lemmaGEN = line[1]
            aux_word_gen.append(wordformGEN)
            aux_lemma_gen.append(lemmaGEN)
        else:
            wrong_element.append(line) ##the cases where both word and lemma are saved with different separator or some random stuff generated by LLM
            number_of_wrong_elements +=1 #in this case we can display all the wrongly generated elements
    else:
        sentence_word_gen.append(aux_word_gen)
        sentence_lemma_gen.append(aux_lemma_gen) 
        aux_word_gen = []
        aux_lemma_gen = []

print(f'number of tokens in the GENerated file:{total_wordforms_gen}')
print(f'number of the wrong elements produced by LLM (output in the wrong format or some randomly generated stuff): {number_of_wrong_elements}')

# ================================
# comparing word-level lemma lists
# ================================
comparison_list = []
for elemGS, elemGEN in zip(sentence_lemma_gs,sentence_lemma_gen):
    comparison_helplist = []
    comparison_string = ''
    if elemGS == elemGEN:
        comparison_helplist.append('coincide:') ##if lemmas in the generated file totally coincide with the one in the GS file
        comparison_helplist.append(str(elemGS))
        comparison_helplist.append(str(elemGEN))
        comparison_string = '\t'.join(comparison_helplist)
        comparison_list.append(comparison_string)
        comparison_string=''
    else:
        comparison_helplist.append('NOT coincide:')
        comparison_helplist.append(str(elemGS))
        comparison_helplist.append(str(elemGEN))
        comparison_string = '\t'.join(comparison_helplist)
        comparison_list.append(comparison_string)
        comparison_string=''        

comparison_gs_vs_gen_dir = os.path.join('./' + folder + '/comparison_gs_vs_gen/')
if not os.path.exists(comparison_gs_vs_gen_dir):
        os.makedirs(comparison_gs_vs_gen_dir)

with open (os.path.join(comparison_gs_vs_gen_dir + 'comparison_gs_vs_gen_' + language + '_' + file_type + '_' + prompt_type + '_' + model + '.tsv'),'w', encoding='utf8') as f1:
     for item in comparison_list:
         f1.write(("%s\n" % item))

##make list of the elements from the list of lists:
def flatten(xss):
    return [x for xs in xss for x in xs]


# ==============================================
# output the elements that are generated wrongly
# ==============================================
print(f'types of the elements that are generated wrongly by LLM: {set(flatten(wrong_element))}')


# ==================================================================
# checking if the number of sentence in the generated file equals GS
# ==================================================================
##we are supposed to have the same number of sentence
##in the case len(sentence lemma GS) != len(sentence lemma GEN), raise ValueError
if len(sentence_lemma_gs) != len(sentence_lemma_gen):
    print(f'the number of the GS sentences is:{len(sentence_lemma_gs)}')
    print(f'the number of the GEN sentences is:{len(sentence_lemma_gen)}')
    raise ValueError ('The number of sentences in the GS file and GEN file are not equal')

# ==================================================================
# generation statistics: lemma correct, input word not correct
#                        word correct, lemma not correct
#                        etc.                  
# ==================================================================
##we want to see how many sentences are generated with correct word but not lemma y vice versa
totally_correct = 0
correct_lemma_but_not_word = 0
correct_word_but_not_lemma = 0
nothing_correct = 0
nothing_correct_list = []
for i in range(len(sentence_lemma_gen)):
    ##correctly generated output (both wordform and lemma):
    if sentence_word_gen[i] == sentence_word_gs[i] and sentence_lemma_gen[i] == sentence_lemma_gs[i]:
        totally_correct +=1
    ##one or more wordforms in the sentence are not generated correctly while all the lemmas are correct
    elif sentence_word_gen[i] != sentence_word_gs[i] and sentence_lemma_gen[i] == sentence_lemma_gs[i]:
        correct_lemma_but_not_word +=1
    ##one or more lemmas in the sentence are not generated correctly while all the wordforms are correct
    elif sentence_word_gen[i] == sentence_word_gs[i] and sentence_lemma_gen[i] != sentence_lemma_gs[i]:
        correct_word_but_not_lemma +=1
    ##one or more lemmas and one or more wordforms in the sentence are not generated correctly
    elif sentence_word_gen[i] != sentence_word_gs[i] and sentence_lemma_gen[i] != sentence_lemma_gs[i]:
        nothing_correct +=1
        aux_nothing = []
        aux_nothing.append(sentence_word_gen[i])
        aux_nothing.append(sentence_word_gs[i])
        aux_nothing.append(sentence_lemma_gen[i])
        aux_nothing.append(sentence_lemma_gs[i])
        nothing_correct_list.append(aux_nothing)

##checking that we did not miss some sentence in the error statistics
if totally_correct + correct_lemma_but_not_word + correct_word_but_not_lemma + nothing_correct != len(sentence_lemma_gen):
    raise ValueError('something wrong in the sentence calculation')

print(f'sentences with correctly generated word and lemma {totally_correct}')
print(f'sentences with correctly generated lemma but not word {correct_lemma_but_not_word}')
print(f'sentences with correctly generated word but not lemma {correct_word_but_not_lemma}')
print(f'sentences with both word and lemma are not correct {nothing_correct}')


##looking how many words were not generated by LLM
gs_wordfroms_not_generated_total = [] #1 ##how many wordforms were not generated at all (in total) #helplist_1
number_gs_wordfroms_not_generated_total = 0
gs_wordfroms_not_generated_correctly = [] ##the original wordform is modified (e.g. lowercased) #helplist_2
number_gs_wordfroms_not_generated_correctly = 0
gs_wordfroms_not_generated_atall = [] ##the case where LLM just skipped (ignored) the word #helplist_3
number_gs_wordfroms_not_generated_atall = 0
number_of_correct_gs_words = 0
acc_per_sentence_list = []
for i in range(len(sentence_word_gs)):
    helplist_1 = []
    helplist_2 = []
    helplist_3 = []
    for item in sentence_word_gs[i]:
        if item in sentence_word_gen[i]:
            number_of_correct_gs_words +=1
        elif item.lower() in sentence_word_gen[i]:
            helplist_1.append(item)
            helplist_2.append(item)
            number_gs_wordfroms_not_generated_total +=1
            number_gs_wordfroms_not_generated_correctly +=1
        else:
            helplist_3.append(item)
            number_gs_wordfroms_not_generated_total +=1
            number_gs_wordfroms_not_generated_atall +=1
    if len(helplist_1) > 0:
        gs_wordfroms_not_generated_total.append(helplist_1) ##either the item is generated wrong or not generated
    if len(helplist_2) > 0:
        gs_wordfroms_not_generated_correctly.append(helplist_2)
    if len(helplist_3) > 0:
        gs_wordfroms_not_generated_atall.append(helplist_3)
print(f'wordforms that are correctly generated from GS: {number_of_correct_gs_words}')
print(f'wordform is generated wrong or not generated: {number_gs_wordfroms_not_generated_total}')
print(f'number of items that were generated but in the wrong format (lowercased): {number_gs_wordfroms_not_generated_correctly}')
print(f'items that were generated but in the wrong format (lowercased): {gs_wordfroms_not_generated_correctly}')
print(f'number of items that were not generated at all by LLM: {number_gs_wordfroms_not_generated_atall}')
print(f'items that were not generated at all by LLM: {gs_wordfroms_not_generated_atall}')

not_generated_elem_dir = os.path.join('./' + folder + '/not_generated_elements/')
if not os.path.exists(not_generated_elem_dir):
        os.makedirs(not_generated_elem_dir)
with open (os.path.join(not_generated_elem_dir + 'not_generated_elements_' + language + '_' + file_type + '_' + prompt_type + '_' + model + '.tsv'), 'w', encoding='utf8') as f2:
     for item in gs_wordfroms_not_generated_atall:
         f2.write(("%s\n" % item))

number_sentences_with_wrongly_generated_wordforms = 0
sentences_with_wrong_wordforms = []
for incorrect_wordforms  in gs_wordfroms_not_generated_total: ##checking how many sentences are subject to the generation errors where the word is wrongly generated (or skipped)
    if len(incorrect_wordforms) > 0:
       number_sentences_with_wrongly_generated_wordforms +=1
       sentences_with_wrong_wordforms.append(incorrect_wordforms)
print(f'wrong wordforms:{sentences_with_wrong_wordforms}')
print(f'sentences with wrong wordforms: {number_sentences_with_wrongly_generated_wordforms}')


# ================================================================
# calculating Word Accuracy (Wacc) and Sentence Accuracy (SentAcc)
# ================================================================

gs_lemmas_not_generated_total = []
number_of_correct_gs_lemmas = 0
number_of_wrong_gs_lemmas = 0
for i in range(len(sentence_lemma_gs)):
    helplist_1 = []
    for item in sentence_lemma_gs[i]:
        if item in sentence_lemma_gen[i]:
            number_of_correct_gs_lemmas +=1
        else:
            helplist_1.append(item)
            number_of_wrong_gs_lemmas +=1
    if len(helplist_1) > 0:
        gs_lemmas_not_generated_total.append(helplist_1) ##either the item is generated wrong or not generated

print(f'lemmas that are correctly generated from GS: {number_of_correct_gs_lemmas}')
print(f'lemmas that are wrongly generated from GS: {number_of_wrong_gs_lemmas}')
Wacc = number_of_correct_gs_lemmas/total_tokens_gs
SentAcc = totally_correct/len(sentence_lemma_gs)
print(f'Wacc: {Wacc}')
print(f'SentAcc: {SentAcc}')


###saving to a file lemmas of GS that were not generated by LLM
wrong_lemmas_dir = os.path.join('./' + folder + '/wrong_lemmas/')
if not os.path.exists(wrong_lemmas_dir):
        os.makedirs(wrong_lemmas_dir)
with open(os.path.join(wrong_lemmas_dir + 'wrong_lemmas_' + language + '_' + file_type + '_' + prompt_type + '_' + model + '.tsv'), 'w', encoding='utf8') as wronglemmas:
     for item in gs_lemmas_not_generated_total:
         wronglemmas.write(("%s\n" % item))
